for file in glob.glob('blog/*.html'):
    if file == 'blog/index.html': continue
    with open(file, 'r', encoding='utf-8') as f:
        content = f.read()
    
    # regex out any <svg ...> that follows title="Bagikan ke Threads" up to </svg>
    # Note: earlier we might have multiple <svg viewBox="0 0 24 24"> so replacing specifically inside the TH link is safer.
    
    def replacer(match):
        return match.group(1) + perfect_th_svg
    
    content = re.sub(r'(class="share-btn th" title="Bagikan ke Threads">\s*)<svg.*?</svg>', replacer, content, flags=re.DOTALL)
    
    with open(file, 'w', encoding='utf-8') as f:
        f.write(content)

print("Threads SVG outer circle removed.")
